from z3 import *

def max_edges_girth_7(n):
    s = Optimize()
    adj = [[Bool(f"e_{i}_{j}") for j in range(n)] for i in range(n)]

    for i in range(n):
        s.add(Not(adj[i][i]))
        for j in range(i + 1, n):
            s.add(adj[i][j] == adj[j][i])

    # Girth >= 7
    import itertools
    for k in range(3, 7):
        for c in itertools.combinations(range(n), k):
            for p in itertools.permutations(c):
                if p[0] == min(p) and p[1] < p[-1]:
                    cycle = [adj[p[i]][p[(i+1)%k]] for i in range(k)]
                    s.add(Not(And(cycle)))

    # Symmetry breaking
    # Degrees are sorted in descending order
    degrees = [Sum([If(adj[i][j], 1, 0) for j in range(n)]) for i in range(n)]
    for i in range(n - 1):
        s.add(degrees[i] >= degrees[i+1])

    edges = Sum([If(adj[i][j], 1, 0) for i in range(n) for j in range(i + 1, n)])
    s.maximize(edges)

    s.set("timeout", 30000)
    if s.check() == sat:
        print("Max edges:", s.model().evaluate(edges))
    else:
        print("UNSAT or Timeout")

