    # length 5
    for c in itertools.combinations(range(V), 5):
        for p in itertools.permutations(c[1:]):
            if p[0] < p[3]:
                solver.add_clause([-edge_var(c[0], p[0]), -edge_var(p[0], p[1]), -edge_var(p[1], p[2]), -edge_var(p[2], p[3]), -edge_var(p[3], c[0])])

